using System.Collections;using System.Reflection;using BepInEx.Configuration;using HSPE;using HSPE.AMModules;using KKAPI.Studio.SaveLoad;using UnityEngine;
static class Tests {
 const BindingFlags All=BindingFlags.Instance|BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic;
 static int checks,failures;static Type T(string name)=>Assembly.GetExecutingAssembly().GetType("J694BindingRestore."+name,true)!;
 static object Call(object o,string name,params object[] args)=>o.GetType().GetMethod(name,All)!.Invoke(o,args);
 static object Field(object o,string name)=>o.GetType().GetField(name,All)!.GetValue(o);
 static void Put(object o,string name,object value)=>o.GetType().GetField(name,All)!.SetValue(o,value);
 static void Check(bool value,string name){checks++;if(!value)failures++;Console.WriteLine((value?"PASS ":"FAIL ")+name);}
 sealed class World {
  internal object Plugin;internal Studio.Studio Studio=new();internal Studio.Info Info=new();internal Studio.OCIChar Character=new();internal GameObject Root=new("Actor"),Clothes;internal ChaControl Control;internal CharaPoseController Pose;internal DynamicBone Body,Cloth;internal DynamicBoneCollider A,B,Foreign;internal CollidersEditor EA=new(),EB=new();
  internal World(){
   Singleton<Studio.Studio>.Instance=Studio;Singleton<Studio.Info>.Instance=Info;CollidersEditor._loneColliders.Clear();StudioSaveLoadApi.LoadInProgress=false;StudioSaveLoadApi.ImportInProgress=false;Time.frameCount=0;
   Control=Root.Add<ChaControl>();Pose=Root.Add<CharaPoseController>();Pose._dynamicBonesEditor=new(){_parent=Pose};Pose._boobsEditor=new();Character.charInfo=Control;Character.guideObject.transformTarget=Root.transform;Character.objectInfo.dicKey=1;Studio.dicObjectCtrl.Add(1,Character);
   Control.objBody=Root.Child("Body");Body=Control.objBody.Child("BodyBone").Add<DynamicBone>();Body.m_Root=Body.transform;
   MakeClothes(100);Pose._dynamicBonesEditor._dynamicBones.Add(Body);Pose._dynamicBonesEditor._dynamicBones.Add(Cloth);
   A=Item(2,"A");B=Item(3,"B");Foreign=new GameObject("Foreign").Add<DynamicBoneCollider>();Body.m_Colliders.Add(Foreign);Cloth.m_Colliders.Add(Foreign);
   CollidersEditor._loneColliders[A]=EA;CollidersEditor._loneColliders[B]=EB;
   EA.SetIgnoreDynamicBone(A,Pose,Body,false);EA.SetIgnoreDynamicBone(A,Pose,Cloth,true);EB.SetIgnoreDynamicBone(B,Pose,Body,true);EB.SetIgnoreDynamicBone(B,Pose,Cloth,false);
   Plugin=Activator.CreateInstance(T("Plugin"),true)!;Put(Plugin,"kkpe",Activator.CreateInstance(T("KkpeAccess"),All,null,new object[]{Assembly.GetExecutingAssembly()},null)!);Put(Plugin,"automaticRestore",new ConfigEntry<bool>(true));Put(Plugin,"keepNewBonesUnchecked",new ConfigEntry<bool>(true));
  }
  internal DynamicBoneCollider Item(int id,string n){var root=new GameObject(n);var c=root.Child("Collider").Add<DynamicBoneCollider>();var item=new Studio.OCIItem();item.guideObject.transformTarget=root.transform;item.itemInfo=new(){group=1,category=1,no=id};Studio.dicObjectCtrl[id]=item;Info.dicItemLoadInfo[1]=Info.dicItemLoadInfo.GetValueOrDefault(1)??new();Info.dicItemLoadInfo[1][1]=Info.dicItemLoadInfo[1].GetValueOrDefault(1)??new();Info.dicItemLoadInfo[1][1][id]=new(){bundlePath="studio/joan6694/dynamic_bone_collider.unity3d",name="Synthetic collider"};return c;}
  internal void MakeClothes(int asset){Clothes=Root.Child("Top");Control.objClothes=new[]{Clothes};Control.infoClothes=new[]{new ListInfoBase{Category=1,Id=asset}};Control.nowCoordinate.clothes.parts=new[]{new ChaFileClothes.PartsInfo{id=asset}};Cloth=Clothes.Child("ClothBone").Add<DynamicBone>();Cloth.m_Root=Cloth.transform;}
  internal DynamicBone ReplaceClothes(int asset){Root.Children.Remove(Clothes);var old=Cloth;old.Destroyed=true;Pose._dynamicBonesEditor._dynamicBones.Remove(old);MakeClothes(asset);Pose._dynamicBonesEditor._dynamicBones.Add(Cloth);Cloth.m_Colliders.Add(A);Cloth.m_Colliders.Add(B);Cloth.m_Colliders.Add(Foreign);return old;}
  internal IDictionary Snapshots=>(IDictionary)Field(Plugin,"snapshots");internal IDictionary Pending=>(IDictionary)Field(Plugin,"pending");
  internal void Load(){Call(Plugin,"OnSceneLoad",null,new SceneLoadEventArgs{Operation=SceneOperationKind.Load});Time.frameCount=20;Call(Plugin,"LateUpdate");}
  internal void Queue(){Call(Plugin,"OnCoordinateLoaded",null,new KKAPI.Chara.CoordinateEventArgs{Character=Control});Time.frameCount++;Call(Plugin,"LateUpdate");}
  internal void Finish(){Time.frameCount+=100;Call(Plugin,"LateUpdate");}
 }
 static void SnapshotsAndReload(){var w=new World();Call(w.Plugin,"OnSceneLoad",null,new SceneLoadEventArgs{Operation=SceneOperationKind.Load});Time.frameCount=19;Call(w.Plugin,"LateUpdate");Check(w.Snapshots.Count==0,"capture waits scene settle frames");Time.frameCount=20;Call(w.Plugin,"LateUpdate");Check(w.Snapshots.Count==1,"actual Capture records scene character");var snapshot=w.Snapshots[w.Character]!;Check(((IDictionary)Field(snapshot,"Bindings")).Count==2,"capture two independent J694 collider bindings");
  w.ReplaceClothes(100);w.EA.SetIgnoreDynamicBone(w.A,w.Pose,w.Body,true);w.Queue();Check(w.Body.m_Colliders.Contains(w.A),"body baseline restored after coordinate event");Check(!w.Cloth.m_Colliders.Contains(w.A)&&w.Cloth.m_Colliders.Contains(w.B),"recreated same asset keeps distinct old collider choices");Check(w.Cloth.m_Colliders.Contains(w.Foreign)&&w.Body.m_Colliders.Contains(w.Foreign),"foreign collider list membership preserved");Check(!w.EA._dirtyColliders[w.A].allDynamicBones[w.Pose][w.Cloth]&&w.EB._dirtyColliders[w.B].allDynamicBones[w.Pose][w.Cloth],"KKPE explicit checkbox table agrees with physical lists");w.Finish();Check(w.Pending.Count==0,"final retry removes pending entry");
  w.EA.SetIgnoreDynamicBone(w.A,w.Pose,w.Body,true);Call(w.Plugin,"LateUpdate");Check(!w.Body.m_Colliders.Contains(w.A),"manual edit remains without another replace event");w.Queue();Check(w.Body.m_Colliders.Contains(w.A),"next edit restores author scene baseline over later manual choice");
 }
 static void OwnersAndSlots(){var w=new World();w.Load();w.ReplaceClothes(200);w.Queue();Check(!w.Cloth.m_Colliders.Contains(w.A)&&!w.Cloth.m_Colliders.Contains(w.B),"same bone path different clothing asset is new and unchecked");Check(w.Cloth.m_Colliders.Contains(w.Foreign),"new owner does not remove foreign collider");w.ReplaceClothes(100);w.Queue();Check(!w.Cloth.m_Colliders.Contains(w.A)&&w.Cloth.m_Colliders.Contains(w.B),"returning original clothing asset restores original bindings");
  var extra=w.Clothes.Child("NewSlotBone").Add<DynamicBone>();extra.m_Root=extra.transform;extra.m_Colliders.Add(w.A);extra.m_Colliders.Add(w.Foreign);w.Queue();Check(!extra.m_Colliders.Contains(w.A)&&extra.m_Colliders.Contains(w.Foreign),"newly discovered inactive-list bone defaults off, foreign remains");
  ((ConfigEntry<bool>)Field(w.Plugin,"keepNewBonesUnchecked")).Value=false;extra.m_Colliders.Add(w.A);w.Queue();Check(extra.m_Colliders.Contains(w.A),"disabled new-bone rule preserves unknown bone state");
  w.Root.Children.Remove(w.Clothes);w.Cloth.Destroyed=true;extra.Destroyed=true;w.Pose._dynamicBonesEditor._dynamicBones.Remove(w.Cloth);w.Control.objClothes=Array.Empty<GameObject>();w.Control.infoClothes=Array.Empty<ListInfoBase>();w.Queue();Check(w.Body.m_Colliders.Contains(w.A),"missing clothing slot does not break body restore");
 }
 static void Lifecycle(){var w=new World();w.Load();Call(w.Plugin,"OnSceneLoad",null,new SceneLoadEventArgs{Operation=SceneOperationKind.Import});Check(w.Snapshots.Count==1,"import does not overwrite baseline");var newChar=new Studio.OCIChar();Call(w.Plugin,"QueueRestore",newChar);Check(w.Pending.Count==0,"new character without snapshot is not queued");
  StudioSaveLoadApi.ImportInProgress=true;w.Queue();Check(w.Pending.Count==0,"import-in-progress gate suppresses restore queue");StudioSaveLoadApi.ImportInProgress=false;StudioSaveLoadApi.LoadInProgress=true;w.Queue();Check(w.Pending.Count==0,"load-in-progress gate suppresses restore queue");StudioSaveLoadApi.LoadInProgress=false;
  Call(w.Plugin,"QueueRestore",w.Character);Check(w.Pending.Count==1,"snapshot character queues");((ConfigEntry<bool>)Field(w.Plugin,"automaticRestore")).Value=false;Call(w.Plugin,"OnAutomaticRestoreChanged",null,EventArgs.Empty);Check(w.Pending.Count==0,"config off immediately clears pending");w.EA.SetIgnoreDynamicBone(w.A,w.Pose,w.Body,true);w.Queue();Check(!w.Body.m_Colliders.Contains(w.A)&&w.Pending.Count==0,"automatic restore off preserves applied manual state");
  ((ConfigEntry<bool>)Field(w.Plugin,"automaticRestore")).Value=true;Call(w.Plugin,"OnCharacterReloaded",null,new KKAPI.Chara.CharaReloadEventArgs{ReloadedCharacter=w.Control});Check(w.Pending.Count==1,"character reload event queues known character");Call(w.Plugin,"ScheduleAfterKkpeRefresh",w.Pose._dynamicBonesEditor);Check((int)Field(w.Pending[w.Character]!,"Next")==Time.frameCount,"actual KKPE refresh callback schedules current frame");
  Call(w.Plugin,"OnDeleted",null,new ObjectDeletedEventArgs{DeletedObject=w.Character});Check(w.Snapshots.Count==0&&w.Pending.Count==0,"deleting character removes baseline and retry state");
  w=new World();w.Load();Call(w.Plugin,"OnSceneLoad",null,new SceneLoadEventArgs{Operation=SceneOperationKind.Clear});Check(w.Snapshots.Count==0&&w.Pending.Count==0&&(int)Field(w.Plugin,"captureAt")==-1,"clear drops baseline and capture timer");
 }
 static void ExclusionsAndInvalidOwners(){var w=new World();var other=w.Root.Child("NestedItem");var external=other.Child("ObjectBone").Add<DynamicBone>();external.m_Root=external.transform;external.m_Colliders.Add(w.A);w.Pose._childObjects.Add(other);w.Load();var keys=(Array)Field(w.Snapshots[w.Character]!,"Keys");Check(keys.Length==2,"nested studio item bones excluded from character snapshot");w.ReplaceClothes(200);w.Queue();Check(external.m_Colliders.Contains(w.A),"nested item collider binding untouched");
  w.A.Destroyed=true;CollidersEditor._loneColliders.Remove(w.A);w.Queue();Check(w.Pending.Count==1,"deleted registered collider skipped without losing pending character");Check(((BepInEx.BaseUnityPlugin)w.Plugin).Logger.Errors.Count==0,"capture and restore produce no boundary errors");
  w=new World();w.Load();var fresh=w.Item(4,"newJ694");var editor=new CollidersEditor();CollidersEditor._loneColliders[fresh]=editor;w.Body.m_Colliders.Add(fresh);w.Queue();Check(w.Body.m_Colliders.Contains(fresh)&&editor.Writes==0,"J694 added after load has no snapshot and is untouched");
 }
 static void Matcher(){var keyType=T("BoneKey");object Key(string owner,int id)=>Activator.CreateInstance(keyType,All,null,new object[]{"DB","Root","Component",null,id,owner},null)!;Array Keys(params object[] values){var a=Array.CreateInstance(keyType,values.Length);for(int i=0;i<values.Length;i++)a.SetValue(values[i],i);return a;}
  var method=T("BindingMatcher").GetMethod("Restore",All)!;bool?[] Run(Array old,bool[] enabled,Array now,bool fresh)=>(bool?[])method.Invoke(null,new object[]{old,enabled,now,fresh})!;
  var a=Run(Keys(Key("clothes:0:100",1)),new[]{true},Keys(Key("clothes:0:200",2)),true);Check(a.Length==1&&a[0]==false,"actual matcher changed owner refuses same path");
  a=Run(Keys(Key("clothes:0:100",1),Key("clothes:0:100",2)),new[]{true,false},Keys(Key("clothes:0:100",3)),false);Check(a[0]==null,"ambiguous duplicate old path stays unresolved");
  a=Run(Keys(Key("body",1)),new[]{true},Keys(Key("body",1)),true);Check(a[0]==true,"live identity match retained");
 }
 static void MultipleCharactersAndBodyKinds(){
  var w=new World();var root=new GameObject("SecondActor");var control=root.Add<ChaControl>();var pose=root.Add<CharaPoseController>();pose._dynamicBonesEditor=new(){_parent=pose};pose._boobsEditor=new();control.objBody=root.Child("Body");var bone=control.objBody.Child("BodyBone").Add<DynamicBone>();bone.m_Root=bone.transform;pose._dynamicBonesEditor._dynamicBones.Add(bone);var character=new Studio.OCIChar{charInfo=control};character.guideObject.transformTarget=root.transform;w.Studio.dicObjectCtrl[5]=character;
  w.EA.SetIgnoreDynamicBone(w.A,pose,bone,true);w.EB.SetIgnoreDynamicBone(w.B,pose,bone,false);
  var body2=w.Control.objBody.Child("Version02").Add<DynamicBone_Ver02>();body2.Root=body2.transform;w.Control.BodyBones[ChaInfo.DynamicBoneKind.Left]=body2;w.Pose._boobsEditor._dynamicBones=new[]{body2};w.EA.SetIgnoreDynamicBone(w.A,w.Pose,body2,true);w.EB.SetIgnoreDynamicBone(w.B,w.Pose,body2,false);body2.Colliders.Add(w.Foreign);
  w.Load();Check(w.Snapshots.Count==2,"two characters captured independently");
  w.EA.SetIgnoreDynamicBone(w.A,pose,bone,false);w.ReplaceClothes(200);w.Queue();Check(bone.m_Colliders.Contains(w.A),"editing first character does not restore second character manual change");
  Call(w.Plugin,"OnCharacterReloaded",null,new KKAPI.Chara.CharaReloadEventArgs{ReloadedCharacter=control});Time.frameCount++;Call(w.Plugin,"LateUpdate");Check(!bone.m_Colliders.Contains(w.A)&&bone.m_Colliders.Contains(w.B),"second character event restores its own baseline");
  body2.Destroyed=true;w.Control.objBody.Children.Remove(body2.gameObject);var bodyNew=w.Control.objBody.Child("ChangedBodyPath").Add<DynamicBone_Ver02>();bodyNew.Root=bodyNew.transform;bodyNew.Colliders.Add(w.A);bodyNew.Colliders.Add(w.B);bodyNew.Colliders.Add(w.Foreign);w.Control.BodyBones[ChaInfo.DynamicBoneKind.Left]=bodyNew;w.Pose._boobsEditor._dynamicBones=new[]{bodyNew};w.Queue();Check(!bodyNew.Colliders.Contains(w.A)&&bodyNew.Colliders.Contains(w.B)&&bodyNew.Colliders.Contains(w.Foreign),"Ver02 body semantic id restores despite changed body root path");w.Finish();Check(!w.EA._dirtyColliders[w.A].allDynamicBones[w.Pose].ContainsKey(body2),"final restore removes destroyed component entries");
 }
 static void StateFormats(){var read=T("KkpeBindingState").GetMethod("Read",All)!;var bone=new object();var collider=new object();var foreign=new object();var exclusions=new HashSet<object>{bone};object legacy=read.Invoke(null,new object[]{exclusions,true,true})!;Check(!(bool)Call(legacy,"IsChecked",bone),"legacy excluded bone reads off");var list=new ArrayList{collider,collider,foreign};int callbacks=0;Action<bool> set=ignore=>{callbacks++;if(ignore)exclusions.Add(bone);else{exclusions.Remove(bone);if(!list.Contains(collider))list.Add(collider);}};Call(legacy,"Apply",bone,list,collider,false,set);Check(list.Count==1&&list.Contains(foreign)&&callbacks==1,"legacy off removes duplicate owned collider only");Call(legacy,"Apply",bone,list,collider,true,set);Check(list.Contains(collider)&&(bool)Call(legacy,"IsChecked",bone),"legacy reenable updates exclusion and list");
  var explicitValues=new Dictionary<object,bool>{{bone,false}};var state=read.Invoke(null,new object[]{explicitValues,false,false})!;Check(!(bool)Call(state,"IsChecked",new object()),"explicit unknown defaults to configured off");Check(!(bool)Call(state,"Apply",bone,new ArrayList{foreign},collider,false,(Action<bool>)(_=>callbacks++)),"explicit same off state does not invoke writer");
 }
 static int Main(){try{SnapshotsAndReload();OwnersAndSlots();Lifecycle();ExclusionsAndInvalidOwners();Matcher();MultipleCharactersAndBodyKinds();StateFormats();Console.WriteLine($"checks={checks} failures={failures}");return failures==0?0:1;}catch(Exception e){Console.Error.WriteLine(e.GetBaseException());return 2;}}
}
